def max_chunks_to_sorted(arr):
    n = len(arr)
    chunks = 0
    for i in range(n):
        prefix_max = max(arr[:i + 1])                           # scan the prefix up to and including i
        suffix_min = min(arr[i + 1:]) if i + 1 < n else float('inf')  # scan everything after i
        if prefix_max <= suffix_min:
            chunks += 1                                             # this is a valid boundary
    return chunks


if __name__ == "__main__":
    arr = [2, 1, 3, 4, 4]
    print(max_chunks_to_sorted(arr))

