public class Main {
    int maxChunksToSorted(int[] arr) {
        int n = arr.length;
        int chunks = 0;
        for (int i = 0; i < n; i++) {
            int prefixMax = Integer.MIN_VALUE;
            for (int j = 0; j <= i; j++) prefixMax = Math.max(prefixMax, arr[j]);    // scan the prefix
            int suffixMin = Integer.MAX_VALUE;
            for (int j = i + 1; j < n; j++) suffixMin = Math.min(suffixMin, arr[j]);  // scan everything after i
            if (prefixMax <= suffixMin) chunks++;                                       // this is a valid boundary
        }
        return chunks;
    }

    public static void main(String[] args) {
        int[] arr = {2, 1, 3, 4, 4};
        Main solution = new Main();
        System.out.println(solution.maxChunksToSorted(arr));
    }
}

