import java.util.*;

public class Main {
    int maxChunksToSorted(int[] arr) {
        Deque<Integer> stack = new ArrayDeque<>();                 // each entry is the max of one chunk seen so far
        for (int num : arr) {
            if (!stack.isEmpty() && stack.peek() > num) {
                int mergedMax = stack.pop();
                while (!stack.isEmpty() && stack.peek() > num) {
                    mergedMax = Math.max(mergedMax, stack.pop());        // keep merging while the top still exceeds num
                }
                stack.push(mergedMax);                                    // this merged chunk's max is at least num
            } else {
                stack.push(num);                                          // this value safely starts its own new chunk
            }
        }
        return stack.size();
    }

    public static void main(String[] args) {
        int[] arr = {2, 1, 3, 4, 4};
        Main solution = new Main();
        System.out.println(solution.maxChunksToSorted(arr));
    }
}

